class UndergroundSystem {
    private java.util.Map<Integer, String[]> checkIns = new java.util.HashMap<>();
    private java.util.Map<String, long[]> routes = new java.util.HashMap<>();
    public UndergroundSystem() {}
    public void checkIn(int id, String stationName, int t) {
        checkIns.put(id, new String[]{stationName, String.valueOf(t)});
    }
    public void checkOut(int id, String stationName, int t) {
        String[] info = checkIns.remove(id);
        String route = info[0] + "->" + stationName;
        long time = t - Integer.parseInt(info[1]);
        routes.computeIfAbsent(route, k -> new long[2]);
        routes.get(route)[0] += time;
        routes.get(route)[1]++;
    }
    public double getAverageTime(String startStation, String endStation) {
        long[] data = routes.get(startStation + "->" + endStation);
        return (double) data[0] / data[1];
    }
}
